<?php
declare(strict_types=1);
require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../config/db.php';
if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: index.php');exit;}verify_csrf();
try{$title=trim((string)($_POST['expense_title']??''));$cat=(int)($_POST['category_id']??0);$amount=(float)($_POST['amount']??0);$method=(string)($_POST['payment_method']??'Cash');$date=(string)($_POST['expense_date']??date('Y-m-d'));$desc=trim((string)($_POST['description']??''));if($title===''||$cat<=0||$amount<=0)throw new RuntimeException('Complete all required expense fields.');if(!in_array($method,['Cash','M-Pesa','Bank','Cheque','Other'],true))throw new RuntimeException('Invalid payment method.');$prefix=(string)($conn->query("SELECT setting_value FROM settings WHERE setting_key='expense_prefix' LIMIT 1")->fetchColumn()?:'SS-EXP');$number=$prefix.'-'.date('YmdHis').'-'.strtoupper(bin2hex(random_bytes(2)));$s=$conn->prepare("INSERT INTO expenses (expense_number,category_id,user_id,expense_title,amount,payment_method,expense_date,description) VALUES (?,?,?,?,?,?,?,?)");$s->execute([$number,$cat,(int)$_SESSION['user_id'],$title,$amount,$method,$date,$desc?:null]);$log=$conn->prepare("INSERT INTO activity_logs (user_id,action,module,description,ip_address) VALUES (?,?,?,?,?)");$log->execute([(int)$_SESSION['user_id'],'Create','Expenses','Recorded expense '.$number.' KES '.number_format($amount,2),$_SERVER['REMOTE_ADDR']??null]);$_SESSION['expense_flash']='Expense '.$number.' recorded successfully.';}catch(Throwable $e){$_SESSION['expense_flash']='Expense failed: '.$e->getMessage();}header('Location: index.php');exit;